import { recordedPrinciplesForPerson } from "./governing/officeholder-principles";
import { libraryMaterialsAuthority } from "./library-materials-authority";
import { LIBRARY_QUESTION } from "./education-civil-law-terms";
import { lawEffectStamp } from "./law-effect-stamp";
import type {
  LibraryDecision,
  LibraryMaterialsStore,
} from "./library-materials-types";
import type { EntityId, PrincipleRecord, World } from "./types";

/** Preserve the existing optional save field without changing the shared World declaration. */
export type LibraryMaterialsWorld = World & {
  readonly libraryMaterials?: LibraryMaterialsStore;
};

/** Content preferences read held continuous support, not old conviction buckets. */
export function libraryContentView(world: World, personId: EntityId) {
  const relevant = new Map(
    Object.values(world.policyCatalog.principles)
      .filter(
        (row) =>
          row.stableKey.endsWith(":tradition") ||
          row.stableKey.endsWith(":personal-liberty"),
      )
      .map((row) => [row.id, row.stableKey.endsWith(":tradition") ? 1 : -1]),
  );
  const held = new Map<EntityId, PrincipleRecord>();
  for (const row of recordedPrinciplesForPerson(world, personId))
    if (row.formedAt <= world.currentDate && relevant.has(row.principleId))
      held.set(row.principleId, row);
  let score = 0;
  const ids: EntityId[] = [];
  for (const row of held.values()) {
    if (row.stance === "conflicted") continue;
    score +=
      relevant.get(row.principleId)! *
      row.strength *
      (row.stance === "endorses" ? 1 : -1);
    ids.push(row.id);
  }
  return { score, ids };
}

/**
 * A held meeting's caller supplies its actual members and existing challenges.
 * A state allocation alone supplies neither a title rule nor state decision makers.
 */
export function resolveLibraryChallenges(
  world: LibraryMaterialsWorld,
  townId: EntityId,
  memberIds: readonly EntityId[],
  meetingKey: string,
): LibraryMaterialsWorld {
  const prior = world.libraryMaterials;
  if (!prior || !meetingKey.trim() || memberIds.length === 0) return world;
  const members = [...new Set(memberIds)];
  if (members.some((id) => !world.people[id])) return world;
  const authority = libraryMaterialsAuthority(world, townId);
  if (authority.level !== "local" || !authority.law) return world;
  const answered = new Set(prior.decisions.map((row) => row.challengeKey));
  const decisions: LibraryDecision[] = [];
  for (const challenge of prior.challenges) {
    if (
      challenge.townId !== townId ||
      challenge.filedOn > world.currentDate ||
      answered.has(challenge.key) ||
      !world.people[challenge.personId]
    )
      continue;
    const ballots = members.map((personId) => {
      const view = libraryContentView(world, personId);
      return {
        personId,
        remove: view.score > 0,
        score: view.score,
        principleRecordIds: view.ids,
        reason:
          view.score > 0
            ? "The member's recorded content preferences favor removal."
            : "The member's recorded content preferences do not favor removal.",
      };
    });
    const stamp = lawEffectStamp(authority.law, {
      effectKind: "library.collection-decision",
      questionKey: LIBRARY_QUESTION,
      jurisdictionId: townId,
      appliedAt: world.currentDate,
      sourceRecordIds: [
        challenge.personId,
        ...challenge.principleRecordIds,
        ...challenge.faithParticipationIds,
        ...challenge.schoolChildIds,
        ...members,
        ...ballots.flatMap((row) => row.principleRecordIds),
      ],
    });
    decisions.push({
      challengeKey: challenge.key,
      meetingKey,
      on: world.currentDate,
      authority: "local",
      authorityReason: authority.reason,
      ballots,
      removed: ballots.filter((row) => row.remove).length > ballots.length / 2,
      staffHours: null,
      legalHours: null,
      expenseCents: null,
      ...(stamp ? { lawEffectStamps: [stamp] } : {}),
    });
    answered.add(challenge.key);
  }
  return decisions.length
    ? {
        ...world,
        libraryMaterials: {
          challenges: prior.challenges,
          decisions: [...prior.decisions, ...decisions],
        },
      }
    : world;
}

import type { LawEffectStampedRecord } from "./law-effect-stamp";
import type { EntityId, IsoDate } from "./types";

export interface LibraryChallenge {
  readonly key: string;
  readonly townId: EntityId;
  readonly personId: EntityId;
  readonly titleKey: string;
  readonly filedOn: IsoDate;
  readonly reason: string;
  readonly principleRecordIds: readonly EntityId[];
  readonly faithParticipationIds: readonly EntityId[];
  readonly schoolChildIds: readonly EntityId[];
}

export interface LibraryDecision extends LawEffectStampedRecord {
  readonly challengeKey: string;
  readonly meetingKey: string;
  readonly on: IsoDate;
  readonly authority: "local" | "state";
  readonly authorityReason: string;
  readonly ballots: readonly {
    personId: EntityId;
    remove: boolean;
    score: number;
    principleRecordIds: readonly EntityId[];
    reason: string;
  }[];
  readonly removed: boolean;
  /** A decision does not prove that a staff or legal-review payment occurred. */
  readonly staffHours: number | null;
  readonly legalHours: number | null;
  readonly expenseCents: number | null;
}

export interface LibraryMaterialsStore {
  readonly challenges: readonly LibraryChallenge[];
  readonly decisions: readonly LibraryDecision[];
}

import {
  CURRICULUM_QUESTION,
  educationCivilLawTermsInForce,
} from "../education-civil-law-terms";
import {
  educationEnrollmentStateAt,
  organizationProfileAt,
} from "../life-queries";
import {
  lifePlaceByJurisdictionId,
  stateKeyForJurisdiction,
} from "../life-places";
import type { EntityId, IsoDate, World } from "../types";
import type { PublicBudgetGovernment } from "./store";

/**
 * Read the governing law and the actual pupils behind a curriculum purchase.
 * A plain yes/no law still has a reading; absent purchase terms are a limit,
 * not evidence that curriculum authority or every other effect is inactive.
 */
export function curriculumAdoptionEffect(
  world: World,
  government: PublicBudgetGovernment,
  month: IsoDate,
) {
  if (government.level !== "state") return null;
  const reading = educationCivilLawTermsInForce(
    world,
    government.lawJurisdictionId,
    CURRICULUM_QUESTION,
    month,
  );
  if (!reading) return null;
  // Count active, represented pupils once each from dated enrollment and school location.
  const pupils = new Map<
    EntityId,
    {
      personId: EntityId;
      enrollmentIds: EntityId[];
      organizationIds: EntityId[];
    }
  >();
  const enrollments = world.history.educationEnrollments
    .filter(
      (row) =>
        row.programKind.startsWith("schooling:") &&
        row.startedAt <= month &&
        (row.recordedAt === undefined || row.recordedAt <= month) &&
        row.sequence < world.history.nextSequence &&
        educationEnrollmentStateAt(world, row.id, {
          asOfDate: month,
          historySequenceExclusive: world.history.nextSequence,
        })?.status === "active",
    )
    .filter((row) => {
      const location = organizationProfileAt(world, row.organizationId, {
        asOfDate: month,
        historySequenceExclusive: world.history.nextSequence,
      })?.locationJurisdictionId;
      if (!location) return false;
      const stateKey =
        lifePlaceByJurisdictionId(location)?.stateJurisdictionKey ??
        (world.jurisdictions[location]
          ? stateKeyForJurisdiction(world.jurisdictions[location]!)
          : null);
      return stateKey === government.stateKey;
    });
  for (const row of enrollments) {
    const pupil = pupils.get(row.personId) ?? {
      personId: row.personId,
      enrollmentIds: [],
      organizationIds: [],
    };
    pupil.enrollmentIds.push(row.id);
    if (!pupil.organizationIds.includes(row.organizationId))
      pupil.organizationIds.push(row.organizationId);
    pupils.set(row.personId, pupil);
  }
  const recipients = [...pupils.values()];
  const result = { law: reading.law, month, recipients };
  const { materialsPerPupilCents, phaseInMonths } = reading.terms?.values ?? {};
  if (materialsPerPupilCents === undefined || !phaseInMonths)
    return {
      ...result,
      spendingDollars: null,
      limit: "No purchase amount and phase-in are filed in the governing law.",
    };
  const elapsed =
    (Number(month.slice(0, 4)) - Number(reading.law.operativeAt.slice(0, 4))) *
      12 +
    Number(month.slice(5, 7)) -
    Number(reading.law.operativeAt.slice(5, 7));

  return {
    ...result,
    spendingDollars:
      elapsed < 0 || elapsed >= phaseInMonths
        ? 0
        : Math.round(
            (recipients.length * materialsPerPupilCents) / 100 / phaseInMonths,
          ),
    limit: null,
  };
}

/** Existing budget settlement consumes only the filed purchase amount. */
export function curriculumAdoptionSpending(
  world: World,
  government: PublicBudgetGovernment,
  month: IsoDate,
): number {
  return (
    curriculumAdoptionEffect(world, government, month)?.spendingDollars ?? 0
  );
}
